class Car {
  constructor(public make: string, public model: string, public color?: string) {}
}

class CarBuilder {
  private make!: string
  private model!: string
  private color?: string

  setMake(make: string) { this.make = make; return this }
  setModel(model: string) { this.model = model; return this }
  setColor(color: string) { this.color = color; return this }
  build() { return new Car(this.make, this.model, this.color) }
}

const car = new CarBuilder().setMake('A').setModel('B').setColor('red').build()

