// Version A: large constructor
class Payment {
  constructor(
    public amount: number,
    public currency: string,
    public method?: string,
    public receiptEmail?: string,
    public metadata?: Record<string,string>
  ) {}
}

// Version B: separate configurator
class PaymentBuilder {
  private opts: Partial<Payment> = {}
  setAmount(a: number) { this.opts.amount = a; return this }
  setCurrency(c: string) { this.opts.currency = c; return this }
  setMethod(m: string) { this.opts.method = m; return this }
  build() { return new Payment(this.opts.amount!, this.opts.currency!, this.opts.method, this.opts.receiptEmail, this.opts.metadata) }
}
